import{_ as e,o as t,c as r,a0 as o}from"./chunks/framework.DqMqoJl9.js";const i=JSON.parse('{"title":"前言","description":"","frontmatter":{},"headers":[],"relativePath":"reactSSR/1_about.md","filePath":"reactSSR/1_about.md","lastUpdated":1791573371000}'),s={name:"reactSSR/1_about.md"};function c(l,a,n,h,_,p){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h1><p>本项目的 demo 地址 <a href="https://github.com/wawjqyh/demo-react-ssr" target="_blank" rel="noreferrer">https://github.com/wawjqyh/demo-react-ssr</a></p><p>页面的渲染模式有两种，分别是客户端渲染(CSR)和服务端渲染(SSR)。</p><h2 id="_1-服务端渲染-ssr" tabindex="-1">1 服务端渲染(SSR) <a class="header-anchor" href="#_1-服务端渲染-ssr" aria-label="Permalink to &quot;1 服务端渲染(SSR)&quot;">​</a></h2><blockquote><p>服务端渲染概念： 是指，浏览器向服务器发出请求页面，服务端将准备好的模板和数据组装成完整的 HTML 返回给浏览器展示</p></blockquote><p>在还没有前端这个职业（前端还是切图仔）的时候，通常是后端包揽了整个网站的开发。使用 ASP、Java、PHP 做后端渲染。</p><h2 id="_2-客户端渲染-csr" tabindex="-1">2 客户端渲染(CSR) <a class="header-anchor" href="#_2-客户端渲染-csr" aria-label="Permalink to &quot;2 客户端渲染(CSR)&quot;">​</a></h2><p>什么是客户端渲染呢？随着 ajax 技术的普及以及前端框架的崛起(jq、Angular、React、Vue) 框架的崛起，开始转向了前端渲染,使用 JS 来渲染页面大部分内容达到局部刷新。就是后台只提供接口，前端只负责页面部分，页面内的数据通过 ajax 调用后端的接口然后由前端渲染出来。像现在主流的三大框架(react vue angular)都是客户端渲染的。</p><h3 id="_2-1-客户端渲染的缺点" tabindex="-1">2.1 客户端渲染的缺点 <a class="header-anchor" href="#_2-1-客户端渲染的缺点" aria-label="Permalink to &quot;2.1 客户端渲染的缺点&quot;">​</a></h3><p>第一个是首屏加载时间(TTFP)比较慢。客户端渲染的流程：</p><p><code>浏览器下载html文档 =&gt; 下载js =&gt; 运行js代码 =&gt; 渲染页面</code></p><p>而且客户端渲染首屏加载的资源都比较多，如果没有做按需加载的话几乎把除多媒体外的整个网站都加载了。当然加载了首屏后跳转其他页面就很快了。</p><p>第二个就是不支持 SEO，这也是重要的一个点，如果一个网站要做 seo 的话不能用客户端渲染的方式（其实也可以，可以用预渲染的方式解决）。</p><h2 id="_3-现代服务端渲染方案" tabindex="-1">3 现代服务端渲染方案 <a class="header-anchor" href="#_3-现代服务端渲染方案" aria-label="Permalink to &quot;3 现代服务端渲染方案&quot;">​</a></h2><p>虽然 react 等框架有极大的便利性，但是现在还是有服务端渲染的需求，比如 SEO。那么如何既能使用 react 又能实现服务端渲染呢？目前也有相关的框架，比如 next.js(对应 react 的应用)和 nuxt.js(对应 vue 的应用)。 下面的主题就是去从 0 开始搭建一套 React 技术栈下的 SSR 框架，深入了解一下 SSR 框架的原理。</p>',15)])])}const u=e(s,[["render",c]]);export{i as __pageData,u as default};
